def augment_message(message, words_to_add):
    """Append good words to the end of a message (append-only attack)."""
    if words_to_add:
        return message + " " + " ".join(words_to_add)
    return message

word_counts = [0, 5, 10, 15, 20, 25, 30]

for num_words in word_counts:
    selected = [w for w, *_ in top_good_words[:num_words]]
    evaded = 0
    for msg in spam_test_messages:
        augmented = augment_message(msg, selected)
        prob = classifier.predict_proba(vectorizer.transform([augmented]))[0]
        if prob[0] > prob[1]:   # ham probability wins
            evaded += 1
    rate = evaded / len(spam_test_messages) * 100
    print(f"Words added: {num_words:2d} | Evasion: {rate:6.2f}%")
